import {LitElement, html} from 'lit';
import {createAtom} from '@tanstack/lit-store';

class NativeFormController {
  constructor(host, store, kind) {
    this.host=host; this.store=store; this.kind=kind;
    this.internals=host.attachInternals(); host.addController(this);
  }
  sync() {
    const s=this.store.get();
    this.internals.setFormValue(this.kind==='checkbox'&&!s.checked?null:s.value);
    const invalid=s.required&&(this.kind==='checkbox'?!s.checked:!s.value);
    this.internals.setValidity(invalid?{valueMissing:true}:{},invalid?'Complete this field.':'',this.host.shadowRoot?.querySelector('input')??undefined);
  }
  hostConnected(){this.sync();this.sub=this.store.subscribe(()=>this.sync());}
  hostDisconnected(){this.sub?.unsubscribe();this.sub=undefined;}
  hostUpdated(){this.sync();}
  associated(){this.sync();}
  disabled(value){this.host.setState({effectiveDisabled:value});}
  reset(){const s=this.store.get();this.host.setState(this.kind==='checkbox'?{checked:s.defaultChecked,dirtyChecked:false}:{value:s.defaultValue,dirtyValue:false});}
}
function formHost(Base){
  return class extends Base {
    static formAssociated=true;
    formAssociatedCallback(){this.formControl.associated();}
    formDisabledCallback(value){this.formControl.disabled(value);}
    formResetCallback(){this.formControl.reset();}
  };
}
for(const kind of ['text','checkbox']) {
  class Probe extends formHost(LitElement) {
    static get observedAttributes(){return [...super.observedAttributes,'value','checked','required'];}
    state=createAtom({value:kind==='checkbox'?'on':'',defaultValue:'',dirtyValue:false,checked:false,defaultChecked:false,dirtyChecked:false,required:false,effectiveDisabled:false});
    formControl=new NativeFormController(this,this.state,kind);
    get value(){return this.state.get().value;}
    set value(v){if(kind==='checkbox')this.setAttribute('value',String(v));else this.setState({value:String(v),dirtyValue:true});}
    get defaultValue(){return this.state.get().defaultValue;}
    set defaultValue(v){this.setAttribute('value',String(v));}
    get checked(){return this.state.get().checked;}
    set checked(v){this.setState({checked:Boolean(v),dirtyChecked:true});}
    get defaultChecked(){return this.state.get().defaultChecked;}
    set defaultChecked(v){this.toggleAttribute('checked',Boolean(v));}
    get required(){return this.state.get().required;}
    set required(v){this.toggleAttribute('required',Boolean(v));}
    get name(){return this.getAttribute('name')??'';}
    set name(v){this.setAttribute('name',v);}
    get disabled(){return this.hasAttribute('disabled');}
    set disabled(v){this.toggleAttribute('disabled',v);}
    attributeChangedCallback(name,old,value){
      super.attributeChangedCallback(name,old,value);
      const s=this.state.get();
      if(name==='value')this.setState({defaultValue:value??'',...(kind==='checkbox'?{value:value??'on'}:!s.dirtyValue?{value:value??''}:{})});
      if(name==='checked')this.setState({defaultChecked:value!==null,...(!s.dirtyChecked?{checked:value!==null}:{})});
      if(name==='required')this.setState({required:value!==null});
    }
    setState(patch){this.state.set(s=>({...s,...patch}));this.formControl.sync();this.requestUpdate();}
    render(){const s=this.state.get();return html`<input aria-label="Probe" type=${kind} .value=${s.value} .checked=${s.checked} ?required=${s.required} ?disabled=${s.effectiveDisabled}>`;}
  }
  customElements.define('refined-form-'+kind,Probe);
}

