import {ScopedRegistryHost} from '@lit-labs/scoped-registry-mixin';
const sheetsByDocument=new WeakMap();
function applyDocumentStyles(host,root) {
  const doc=host.ownerDocument,C=host.constructor;
  let byClass=sheetsByDocument.get(doc);
  if(!byClass)sheetsByDocument.set(doc,byClass=new WeakMap());
  let sheets=byClass.get(C);
  if(!sheets){
    sheets=(C.elementStyles??[]).map(style=>{
      const sheet=new doc.defaultView.CSSStyleSheet();
      sheet.replaceSync(style.cssText??Array.from(style.cssRules,rule=>rule.cssText).join('\n'));
      return sheet;
    });
    byClass.set(C,sheets);
  }
  root.adoptedStyleSheets=sheets;
}
export function NativeFirstRegistryHost(Base) {
  const native=window.bootstrap.capability.supported;
  return class extends(native?Base:ScopedRegistryHost(Base)) {
    createRenderRoot() {
      const C=this.constructor;
      if(!Object.hasOwn(C,'registry')) {
        C.registry=new CustomElementRegistry();
        for(const [tag,Class] of Object.entries(C.elementDefinitions??{}))C.registry.define(tag,Class);
      }
      let root;
      if(!native)root=super.createRenderRoot();
      else{
        root=this.shadowRoot??this.attachShadow({...C.shadowRootOptions,customElementRegistry:C.registry});
        this.renderOptions.creationScope={importNode:(node,deep=false)=>this.ownerDocument.importNode(node,{customElementRegistry:C.registry,selfOnly:!deep})};
      }
      applyDocumentStyles(this,root);
      return root;
    }
    adoptedCallback(oldDocument,newDocument) {
      super.adoptedCallback?.(oldDocument,newDocument);
      if(this.renderRoot)applyDocumentStyles(this,this.renderRoot);
    }
  };
}

