 const lateObserved={sameNodes:a.shadowRoot.querySelector('late-item')===lateA&&b.shadowRoot.querySelector('late-item')===lateB,constructorA:lateA instanceof LateA,constructorB:lateB instanceof LateB,textA:lateA.textContent,textB:lateB.textContent};
