import {transform, Features} from "lightningcss";
import {writeFile} from "node:fs/promises";
import assert from "node:assert/strict";
const root="/Users/peterkloss/Dev/ACMElabs/design-system";
const work=import.meta.dir;
const tick=String.fromCharCode(96);
const checks=[];
function check(name,fn){console.log(name);fn();checks.push({name,pass:true});}
const registration='@property --m00-length { syntax: "<length>"; inherits: false; initial-value: 2px; }\n';
const fixture=registration+'\n:host { display: block; --m00-length: 19px; }\n.outer { --m00-length: 17px; & .length { width: var(--m00-length); } }\n.escape::after { content: "backtick: '+tick+' interpolation: $'+'{literal} slash: \\\\ é"; }\n.scope { container-type: inline-size; width: 200px; }\n@container (min-width: 150px) { .nested { color: rgb(1 2 3); } }\n';
await writeFile(work+"/fixture.css",fixture);
const actual={};
for(const name of ["button","separator"]){
 const mod=await import(root+"/src/components/"+name+"/"+name+".styles.ts");
 actual[name]=mod[name+"Css"].cssText;
 await writeFile(work+"/"+name+".css",actual[name]);
}
function compile(name,text){return transform({filename:name,code:Buffer.from(text),sourceMap:true,minify:false,include:Features.Nesting,targets:{chrome:120<<16,firefox:128<<16,safari:18<<16}});}
const compiled={};
for(const [name,source]of Object.entries({...actual,fixture})){
 const result=compile(name+".css",source);
 const css=result.code.toString();
 const map=JSON.parse(result.map.toString());
 compiled[name]={css,map};
 check(name+" determinism",()=>assert.deepEqual(compile(name+".css",source),result));
 check(name+" original source",()=>{assert.equal(map.sources[0],name+".css");assert.equal(map.sourcesContent[0],source);assert.ok(map.mappings.length>10);});
 await writeFile(work+"/"+name+".compiled.css",css);
 await writeFile(work+"/"+name+".css.map",JSON.stringify(map));
}
check("invalid CSS fails",()=>assert.throws(()=>compile("invalid.css","a { color: rgb(; }")));
check("nested selector compiled",()=>assert.ok(!compiled.fixture.css.includes("& .length")));
const registrations=new Map();
function collect(source){
 transform({filename:"registrations.css",code:Buffer.from(source),visitor:{Rule(rule){
  if(rule.type!=="property")return;
  const {loc,...definition}=rule.value;
  const value=JSON.stringify(definition);
  const previous=registrations.get(definition.name);
  if(previous&&previous!==value)throw new Error("conflicting registration "+definition.name);
  registrations.set(definition.name,value);
 }}});
}
check("same registration deduplicates",()=>{collect(registration);collect(registration);assert.equal(registrations.size,1);});
check("conflicting registration fails",()=>assert.throws(()=>collect(registration.replace("2px","3px")),/conflicting registration/));
function vlq(text){let value=0,shift=0,values=[];for(const c of text){const n="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/".indexOf(c);value|=(n&31)<<shift;if(n&32)shift+=5;else{values.push(value&1?-(value>>1):value>>1);value=0;shift=0;}}return values;}
const map=compiled.separator.map;
let source=0,line=0,column=0;const locations=[];
for(const [generatedLine,segments] of map.mappings.split(";").entries()){
 let generatedColumn=0;
 for(const segment of segments.split(",")){if(!segment)continue;const v=vlq(segment);generatedColumn+=v[0];if(v.length>=4){source+=v[1];line+=v[2];column+=v[3];locations.push({generatedLine,generatedColumn,source,line,column});}}
}
check("selector map resolves to authored selector",()=>{
 const generated=compiled.separator.css.split("\n");
 assert.ok(locations.some(x=>generated[x.generatedLine].slice(x.generatedColumn).startsWith(".separator")&&actual.separator.split("\n")[x.line].slice(x.column).startsWith(".separator")));
});
const escape=s=>s.replaceAll("\\","\\\\").replaceAll(tick,"\\"+tick).replaceAll("$"+"{","\\$"+"{");
const modules=Object.entries(compiled).map(([n,{css}])=>"export const "+n+"Css=css"+tick+escape(css)+tick+";").join("\n");
await writeFile(work+"/generated.js",'import {css} from "lit";\n'+modules);
const generated=await import(work+"/generated.js");
check("Lit template escaping exact",()=>{for(const [n,{css}]of Object.entries(compiled))assert.equal(generated[n+"Css"].cssText,css);});
const browser='import {LitElement,html,css} from "lit";\nimport {buttonCss,separatorCss,fixtureCss} from "./generated.js";\nclass StylesProbe extends LitElement{\nstatic styles=[css'+tick+':host{--ds-gray-1000:#111;--ds-background-100:#fff;--ds-gray-200:#ccc;--acme-gap-half:4px;--x-padding:0;display:block}.outer{height:30px;width:100px}'+tick+',buttonCss,separatorCss,fixtureCss];\nrender(){return html'+tick+'<button class="btn tiny icon"><span class="label">A</span></button><div class="outer"><div class="separator"></div><div class="separator vertical"></div><div class="length"></div></div><div class="scope"><div class="nested">Nested</div></div><span class="escape"></span>'+tick+';}}\ncustomElements.define("styles-probe",StylesProbe);';
await writeFile(work+"/browser.js",browser);
const bundle=await Bun.build({entrypoints:[work+"/browser.js"],target:"browser",write:false});
assert.ok(bundle.success);
await writeFile(work+"/browser-bundle.js",await bundle.outputs[0].text());
const documentCSS='[data-m00-native] > ul { margin: 0; padding: 0; list-style: none; color: rgb(4 5 6); }\n';
const compiledDocument=compile("native.css",documentCSS).code.toString();
const server=Bun.serve({port:0,fetch(request){
 if(new URL(request.url).pathname==="/app.js")return new Response(Bun.file(work+"/browser-bundle.js"),{headers:{"Content-Type":"text/javascript"}});
 return new Response('<!doctype html><html><head><style>'+registration+compiledDocument+'</style></head><body><styles-probe></styles-probe><div data-m00-native><ul><li>Scoped</li></ul></div><ul id="outside"><li>Unscoped</li></ul><script type="module" src="/app.js"></script></body></html>',{headers:{"Content-Type":"text/html"}});
}});
process.env.PLAYWRIGHT_BROWSERS_PATH="/var/folders/b6/2r9mrtsj70s3x013xbhxt2yr0000gn/T/acme-style-engines-fHTyxk/browsers";
const pw=await import("/var/folders/b6/2r9mrtsj70s3x013xbhxt2yr0000gn/T/acme-style-engines-fHTyxk/package/index.mjs");
const browsers=[];
try{
 for(const engine of ["chromium","firefox","webkit"]){
 const b=await pw[engine].launch(engine==="chromium"?{headless:true,executablePath:"/Applications/Google Chrome.app/Contents/MacOS/Google Chrome"}:{headless:true});
 try{
 const page=await b.newPage();const errors=[];page.on("pageerror",e=>errors.push(e.message));
 await page.goto(server.url.href);await page.waitForFunction(()=>document.querySelector("styles-probe")?.shadowRoot?.querySelector(".btn"));
 const values=await page.evaluate(()=>{
 const host=document.querySelector("styles-probe"),s=host.shadowRoot;
 const prop=(sel,key)=>getComputedStyle(s.querySelector(sel))[key];
 return {buttonHeight:prop(".btn","height"),buttonWidth:prop(".btn","width"),buttonColor:prop(".btn","backgroundColor"),horizontalHeight:prop(".separator:not(.vertical)","height"),horizontalWidth:prop(".separator:not(.vertical)","width"),verticalHeight:prop(".vertical","height"),verticalWidth:prop(".vertical","width"),registeredLength:prop(".length","width"),containerColor:prop(".nested","color"),escape:getComputedStyle(s.querySelector(".escape"),"::after").content,scopeColor:getComputedStyle(document.querySelector("[data-m00-native] > ul")).color,outsideColor:getComputedStyle(document.querySelector("#outside")).color};
 });
 assert.equal(values.buttonHeight,"24px");assert.equal(values.buttonWidth,"24px");assert.equal(values.buttonColor,"rgb(17, 17, 17)");
 assert.equal(values.horizontalHeight,"1px");assert.equal(values.horizontalWidth,"100px");assert.equal(values.verticalWidth,"1px");assert.equal(values.verticalHeight,"30px");
 assert.equal(values.registeredLength,"2px");assert.equal(values.containerColor,"rgb(1, 2, 3)");assert.ok(values.escape.includes("$"+"{literal}"));assert.ok(values.escape.includes("backtick: "+tick));
 assert.equal(values.scopeColor,"rgb(4, 5, 6)");assert.notEqual(values.outsideColor,values.scopeColor);assert.deepEqual(errors,[]);
 browsers.push({engine,version:b.version(),values,errors,pass:true});
 }finally{await b.close();}
 }
}finally{server.stop(true);}
const result={date:"2026-09-20",bun:Bun.version,compiler:"lightningcss@1.33.0",status:"scratch candidate only; not selected or installed in project",checks,browsers,limits:["No continuous authored-CSS to final JS source-map chain yet","Two real house styles and small boundary fixtures; not full generator corpus","Registration conflict checker is a scratch proof, not production implementation","Document scope is explicitly authored, not automatic shadow selector conversion"]};
await writeFile(work+"/css-results.json",JSON.stringify(result,null,2));
console.log(JSON.stringify(result,null,2));

