import {mkdir,writeFile} from "node:fs/promises";
import assert from "node:assert/strict";
const work=import.meta.dir+"/release-fixture";
await mkdir(work,{recursive:true});
await writeFile(work+"/package.json",JSON.stringify({name:"acme-m00-publish-probe",version:"0.0.0",files:["index.js"],scripts:{prepack:"exit 91"}}));
await writeFile(work+"/index.js","export const probe = true;\n");
await writeFile(work+"/user.npmrc","");
await writeFile(work+"/global.npmrc","");
const cleanEnv={PATH:process.env.PATH,TMPDIR:process.env.TMPDIR,NPM_CONFIG_USERCONFIG:work+"/user.npmrc",NPM_CONFIG_GLOBALCONFIG:work+"/global.npmrc",NPM_CONFIG_CACHE:work+"/cache"};
const npm=import.meta.dir+"/node_modules/npm/bin/npm-cli.js";
const child=Bun.spawn([process.execPath,npm,"pack","--json","--ignore-scripts","--registry=http://127.0.0.1:1","--pack-destination",work],{cwd:work,env:cleanEnv,stdout:"pipe",stderr:"pipe"});
const [stdout,stderr,code]=await Promise.all([new Response(child.stdout).text(),new Response(child.stderr).text(),child.exited]);
assert.equal(code,0);const packOutput=JSON.parse(stdout);console.log(packOutput);const packed=Array.isArray(packOutput)?packOutput:Object.values(packOutput);assert.ok(packed[0].files.some(x=>x.path==="index.js"));
process.env.GITHUB_ACTIONS="true";process.env.CI="true";
const calls=[];
const token="test-header."+Buffer.from(JSON.stringify({repository_visibility:"public"})).toString("base64url")+".test-signature";
const server=Bun.serve({port:0,fetch:async(req)=>{
 const u=new URL(req.url);
 calls.push({method:req.method,path:u.pathname,audience:u.searchParams.get("audience"),hasAuthorization:req.headers.has("authorization")});
 if(u.pathname==="/oidc")return Response.json({value:token});
 if(u.pathname==="/-/npm/v1/oidc/token/exchange/package/acme-m00-publish-probe")return Response.json({token:"local-fake-registry-token"});
 if(u.pathname==="/-/package/acme-m00-publish-probe/visibility")return Response.json({public:true});
 return new Response("unexpected mock endpoint",{status:404});
}});
process.env.ACTIONS_ID_TOKEN_REQUEST_URL=server.url.href+"oidc";
process.env.ACTIONS_ID_TOKEN_REQUEST_TOKEN="local-fake-actions-token";
const opts={registry:server.url.href};
const writes=[];
const config={isDefault:key=>key==="provenance",set:(key,value,where)=>writes.push({key,value:key.includes("authToken")?"[LOCAL TEST TOKEN]":value,where})};
try{
 const exchange=(await import(import.meta.dir+"/node_modules/npm/lib/utils/oidc.js")).oidc;
 await exchange({packageName:"acme-m00-publish-probe",registry:server.url.href,opts,config});
 assert.equal(opts.provenance,true);
 assert.ok(Object.keys(opts).some(key=>key.endsWith(":_authToken")));
 assert.equal(calls.length,3);
 assert.equal(calls[0].audience,"npm:"+server.url.hostname);
 assert.ok(calls.every(x=>x.hasAuthorization));
}finally{server.stop(true);}
const result={bun:Bun.version,npm:"12.0.2",pack:{exitCode:code,files:packed[0].files.map(x=>x.path),integrity:packed[0].integrity,stderr},oidcMock:{calls,writes,automaticPublicProvenance:opts.provenance},limits:["Local mock tests only; no trusted publisher account/configuration was used or changed","No package published and no signing/transparency service contacted","npm officially documents Node requirements; this proves bounded execution under Bun, not official Bun support","Sigstore signing and CI platform integration remain unverified"]};
await writeFile(import.meta.dir+"/release-results.json",JSON.stringify(result,null,2));
console.log(JSON.stringify(result,null,2));
